"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["99679"],{55112(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.grupo_formulario.campo_com_secao_propria","status":422,"titulo":"O campo do grupo segue a se\xe7\xe3o do grupo"},"descricao":{"codigo":"uniplus.grupo_formulario.campo_com_secao_propria","requisitos":["UNI-REQ-0146"],"oQueAconteceu":["Um campo de um grupo repet\xedvel (um item de `subitens` de um grupo em `grupos`) traz `etapaCodigo`. O campo aparece onde o grupo aparece, na se\xe7\xe3o do pr\xf3prio grupo, e por isso n\xe3o declara se\xe7\xe3o pr\xf3pria (UNI-REQ-0146).","A recusa vem na lista `errors` da resposta, com `field` igual a `grupos[i].subitens[j].etapaCodigo`, e a mensagem diz que o campo, pelo c\xf3digo do fato, segue a se\xe7\xe3o do grupo e n\xe3o declara se\xe7\xe3o pr\xf3pria. Na cria\xe7\xe3o e na atualiza\xe7\xe3o de um modelo de formul\xe1rio o `field` come\xe7a por `conteudo.`. H\xe1 uma entrada por campo com `etapaCodigo`, no mesmo lote das demais recusas da forma do grupo. Nada \xe9 gravado.","Na grava\xe7\xe3o dos itens do formul\xe1rio, a recusa vem junto com as outras recusas da forma dos grupos e dos itens, antes de o cat\xe1logo de fatos ser consultado. Nos modelos, ela s\xf3 \xe9 conferida quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Retire `etapaCodigo` do campo do grupo. Se o grupo deve aparecer em outra se\xe7\xe3o, mude o `etapaCodigo` do pr\xf3prio grupo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Grupo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);